<?php
/** Proof — draft, lines, the strip (spec "Proof", 1): out by 1,000 and Post disabled, the endpoint refused in the trigger's words, both sides → "A line is a debit or a credit.", (100.00) becomes a credit, balanced after two more lines, the period chip follows the date, a date with no year. */
require __DIR__ . '/lib.php';
$owner = as_member(1); $bea = as_member(27);
ensure_year($owner);
echo "1. A draft out of balance\n";
$since = last_activity_id();
[$c, $b, $id] = draft($bea, '2026-04-10', [['account' => '6100', 'debit' => '11,000.00', 'description' => 'SMOKE rent'], ['account' => '1010', 'credit' => '10000']], 'SMOKE April rent');
ok($c === 200 && $id > 0 && ($b['location'] ?? '') === '/journal/' . $id . '?notice=saved' && str_starts_with((string) $b['did'], 'Drafted entry'), "journal_entry_draft: 200, record_id $id, location the entry");
$log = activity('journal_entry.draft', $since);
ok(count($log) === 1 && (int) $log[0]['journal_entry_id'] === $id && str_contains((string) $log[0]['after'], '"lines": 2'), 'journal_entry.draft logged with journal_entry_id and the lines count');
$d = entry_json($bea, $id);
ok($d['entry']['status'] === 'draft' && $d['balance']['difference'] === '1000.00' && $d['balance']['balances'] === false && $d['entry']['period']['name'] === '2026-04' && $d['entry']['lines'][0]['debit'] === '11000.00', 'the entry: draft, out by 1000.00, period 2026-04 from the date, 11,000.00 parsed');
$body = page($bea, '/journal/' . $id)['body'];
ok(preg_match('/id="entry-balance-state">out by 1,000\.00</', $body) === 1 && preg_match('/id="entry-post-btn"[^>]*disabled/', $body) === 1 && str_contains($body, 'It must balance first.'), 'the strip says "out by 1,000.00" and Post is disabled');
[$c, $b] = act($bea, '/journal/post.php', ['entry' => $id]);
ok($c === 422 && msg($b) === 'Entry does not balance: debits 11000.00, credits 10000.00 (difference 1000.00)', 'the endpoint called anyway: 422 in the trigger\'s words');
ok(entry_status($id) === 'draft' && one('SELECT number FROM journal_entries WHERE id = :i', ['i' => $id]) === null, 'still a draft, no number');
echo "2. Lines\n";
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'account' => account_id('6100'), 'debit' => '5', 'credit' => '5']);
ok($c === 422 && msg($b) === 'A line is a debit or a credit.', 'a line with both sides: 422 "A line is a debit or a credit."');
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'account' => account_id('6100'), 'debit' => '0', 'credit' => '']);
ok($c === 422 && msg($b) === 'A line is a debit or a credit.', 'a zero line: 422 the same');
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'account' => '6100', 'debit' => '(100.00)', 'description' => 'SMOKE negative debit']);
$l3 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $l3 > 0 && (string) one('SELECT credit FROM journal_lines WHERE id = :l', ['l' => $l3]) === '100.00' && (string) one('SELECT debit FROM journal_lines WHERE id = :l', ['l' => $l3]) === '0.00', '"(100.00)" in debit becomes a credit of 100.00');
ok(($b['balance']['difference'] ?? '') === '900.00', 'the answer carries the strip (out by 900.00 now)');
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'account' => '1010', 'credit' => '900', 'description' => 'SMOKE balancing']);
$l4 = (int) $b['record_id'];
ok($c === 200 && ($b['balance']['balances'] ?? false) === true, 'a fourth line balances it');
$body = page($bea, '/journal/' . $id)['body'];
ok(preg_match('/id="entry-balance-state">balances</', $body) === 1 && preg_match('/id="entry-post-btn"(?![^>]*disabled)/', $body) === 1 && str_contains($body, 'id="entry-line-' . $l4 . '"') && str_contains($body, 'id="entry-line-new"'), 'the strip says "balances", Post is enabled, the editor shows the lines and the add row');
$since = last_activity_id();
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'line' => $l3, 'credit' => '150']);
ok($c === 200 && (string) one('SELECT credit FROM journal_lines WHERE id = :l', ['l' => $l3]) === '150.00' && (string) one('SELECT description FROM journal_lines WHERE id = :l', ['l' => $l3]) === 'SMOKE negative debit', 'changing a line keeps what was not sent');
$log = activity('journal_entry.line_save', $since);
ok(count($log) === 1 && str_contains((string) $log[0]['before'], '"credit": "100.00"') && str_contains((string) $log[0]['after'], '"credit": "150.00"') && str_contains((string) $log[0]['after'], '"account_code": "6100"'), 'journal_entry.line_save logs before/after with the account code');
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'line' => $l3, 'credit' => '100']);
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'account' => 'No such account', 'debit' => '1']);
ok($c === 422 && stripos(msg($b), 'no account called No such account') !== false, 'an unknown account: 422 naming it');
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $id, 'account' => 'Rent', 'debit' => '1']);
$byName = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (int) one('SELECT account_id FROM journal_lines WHERE id = :l', ['l' => $byName]) === account_id('6100'), 'an account by its exact name resolves (Rent → 6100)');
$since = last_activity_id();
[$c, $b] = act($bea, '/journal/line-remove.php', ['entry' => $id, 'line' => $byName]);
ok($c === 200 && one('SELECT 1 FROM journal_lines WHERE id = :l', ['l' => $byName]) === false && count(activity('journal_entry.line_remove', $since)) === 1, 'journal_line_remove: gone, logged');
$r = req('POST', '/journal/line-save.php', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: entry-lines'], 'form' => ['entry' => $id, 'account' => '6100', 'debit' => '1', 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
ok($r['code'] === 200 && str_starts_with(trim($r['body']), '<div id="entry-lines"') && str_contains($r['body'], 'id="entry-balance" hx-swap-oob="true"') && str_contains($r['headers'], 'HX-Trigger: journalEntryChanged'), 'under HTMX a line write re-renders #entry-lines with the strip out of band');
$extra = (int) one('SELECT id FROM journal_lines WHERE entry_id = :e ORDER BY id DESC LIMIT 1', ['e' => $id]);
act($bea, '/journal/line-remove.php', ['entry' => $id, 'line' => $extra]);
echo "3. The head and the period\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/journal/save.php', ['entry' => $id, 'entry_date' => '2026-05-03']);
ok($c === 200 && ($b['changed'] ?? []) === ['entry_date'] && entry_json($bea, $id)['entry']['period']['name'] === '2026-05', 'journal_entry_update with the date: the period follows (2026-05)');
ok(count(activity('journal_entry.update', $since)) === 1 && json_decode((string) activity('journal_entry.update', $since)[0]['before'], true) === ['entry_date' => '2026-04-10'], 'journal_entry.update logs before/after of the changed field');
[$c, $b] = act($bea, '/journal/save.php', ['entry' => $id, 'entry_date' => '2027-03-01']);
ok($c === 200 && entry_json($bea, $id)['entry']['period'] === null, 'a date with no fiscal year: the entry has no period');
ok(str_contains(page($bea, '/journal/' . $id)['body'], 'id="entry-balance-period">no period<'), 'the chip says "no period"');
[$c, $b] = act($bea, '/journal/post.php', ['entry' => $id]);
ok($c === 422 && msg($b) === 'No fiscal period covers 2027-03-01 — open the fiscal year first', 'posting it: 422 "No fiscal period covers …"');
act($bea, '/journal/save.php', ['entry' => $id, 'entry_date' => '2026-04-10']);
[$c, $b] = act($bea, '/journal/save.php', ['entry_date' => 'soon', 'memo' => 'x']);
ok($c === 422 && isset(fields($b)['entry_date']), 'a bad date on a draft: 422 (field entry_date)');
[$c, $b] = act($bea, '/journal/save.php', ['entry_date' => '2026-04-11', 'lines' => json_encode([['account' => '9999', 'debit' => '1'], ['account' => '6100', 'credit' => '1']])]);
ok($c === 422 && str_contains(msg($b), 'Row 1: no account called 9999') && (fields($b)['row'] ?? 0) === 1, 'a draft with an unknown account in row 1: 422 naming the row');
[$c, $b] = act($bea, '/journal/save.php', ['entry_date' => '2026-04-11', 'line_account' => [account_id('6100'), '', account_id('1010')], 'line_description' => ['SMOKE form', '', ''], 'line_debit' => ['10', '', ''], 'line_credit' => ['', '', '10']]);
$f = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $f > 0 && (int) one('SELECT count(*) FROM journal_lines WHERE entry_id = :e', ['e' => $f]) === 2, 'the browser form\'s line arrays make the lines (a blank row skipped)');
ok(page(as_member(26), '/journal/' . $id)['code'] === 200 && page(as_member(26), '/journal/new')['code'] === 403, 'a Viewer reads the entry (documents.view) and may not draft (403)');
ok(page($bea, '/journal/424242')['code'] === 404, 'an unknown entry: 404');
finish();
